-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.approve_team_member(p_profile uuid, p_role_title text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_global_admin() then
    raise exception 'Only a platform admin can approve somebody onto the team.';
  end if;
  update public.profiles
     set is_admin = true,
         platform_role = case when platform_role = 'owner' then platform_role else 'global_admin' end,
         status = 'active',
         role_title = coalesce(nullif(trim(coalesce(p_role_title, '')), ''), role_title, requested_role_title),
         team_application = false
   where id = p_profile;
end;
$function$;
